mapper.update:
update platform_access_token
   set last_used_at = #{lastUsedAt}
 where id = #{id}

mapper.select:
select id, subject_type, subject_id
  from platform_access_token
 where id = #{id}

mapper.update:
update platform_access_token
   set status = 'REVOKED',
       revoked_at = #{revokedAt}
 where id = #{id}
   and status = 'ACTIVE'

mapper.delete:
delete from platform_access_token
 where id = 'token-bootstrap'
   and token_hash <> #{tokenHash}

mapper.select:
select id, username, display_name, status, created_at
  from user_account
 where username = #{username}

mapper.update:
update user_account
   set username = #{newUsername},
       display_name = #{displayName}
 where username = #{oldUsername}
   and status = 'ACTIVE'

update platform_access_token
   set subject_id = #{newUsername},
       display_name = #{displayName}
 where subject_type = 'USER'
   and subject_id = #{oldUsername}

update platform_access_token
   set status = 'REVOKED',
       revoked_at = #{revokedAt}
 where subject_type = 'USER'
   and subject_id = #{username}
   and status = 'ACTIVE'

mapper.delete:
delete from platform_access_token
 where subject_type = 'USER'
   and subject_id = #{username}
